import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { strToU8, zipSync } from 'fflate';
import type { Page } from '@playwright/test';
import { addPerson, expect, importFromPeople, overflowsHorizontally, personMenu, startFresh, test } from './fixtures';

/**
 * Two devices, by hand: a changes file made in one browser context is opened in another (a fresh context is a clean OPFS,
 * so a different device). Synthetic names only; the file is generated by the app and carried through a temp directory.
 */
const chat = {
  name: 'WhatsApp Chat - Ana i Mama.zip',
  mimeType: 'application/zip',
  buffer: Buffer.from(
    zipSync({
      '_chat.txt': strToU8(['[17/03/2026, 13:17:05] Ana: Bon dia Mama', '[17/03/2026, 13:17:30] Mama: Hola Ana', '[18/03/2026, 09:10:00] Mama: Fins demà'].join('\n')),
    }),
  ),
};

test('a changes file made on one device is merged on another, and its own file is refused', async ({ page, browser }, testInfo) => {
  test.setTimeout(120_000);
  const dir = mkdtempSync(join(tmpdir(), 'ma-sync-e2e-'));
  const foreign: string[] = [];
  const use = testInfo.project.use;
  const baseURL = use.baseURL!;
  const context = await browser.newContext({
    baseURL,
    locale: 'en-US',
    viewport: use.viewport,
    isMobile: use.isMobile,
    hasTouch: use.hasTouch,
    deviceScaleFactor: use.deviceScaleFactor,
    acceptDownloads: true,
  });
  context.on('request', (request) => {
    const url = request.url();
    if (!/^(data|blob|about):/.test(url) && new URL(url).origin !== new URL(baseURL).origin) foreign.push(url);
  });
  try {
    // Device A: an archive with one person and three messages.
    await startFresh(page);
    await addPerson(page, 'Mama');
    await importFromPeople(page, chat, 'Mama', 'Add 3 messages to Mama');
    await expect(page.getByText('3 new messages added to Mama.')).toBeVisible();

    await page.goto('/en/settings/');
    await page.getByRole('link', { name: /^Sync devices/ }).click();
    await expect(page.getByRole('heading', { level: 1, name: 'Sync devices' })).toBeVisible();
    const code = (await page.getByTestId('sync-device-code').innerText()).trim();
    expect(code).toMatch(/^[0-9a-f]{8}$/);
    expect(await overflowsHorizontally(page)).toBe(false);

    // A new device gets everything. The file is private (no password), and there is no "did you hand it over" step.
    const downloading = page.waitForEvent('download');
    await page.getByRole('button', { name: 'Make the file' }).click();
    const download = await downloading;
    expect(download.suggestedFilename()).toMatch(/^memory-archive-changes-.*\.zip$/);
    const result = page.getByTestId('sync-export-result');
    await expect(result).toContainText('The file was made', { timeout: 60_000 });
    await expect(result).toContainText('Check your Downloads folder');
    await expect(result).toContainText('anyone who has it can read it');
    await expect(page.getByText(/Did you hand .* to device/)).toHaveCount(0);
    const path = join(dir, download.suggestedFilename());
    await download.saveAs(path);

    // Device B: empty. Opens the file.
    const second = await context.newPage();
    await startFresh(second);
    await second.goto('/en/sync/');
    await expect(second.getByTestId('sync-peers')).toHaveCount(0);
    await second.getByTestId('sync-input').setInputFiles(path);
    const merged = second.getByTestId('sync-import-result');
    await expect(merged).toContainText('The changes were added', { timeout: 60_000 });
    await expect(merged).toContainText('3 new messages added.');
    await expect(merged).toContainText('1 person added or updated.');
    // The sender is now a known device, and the pack can be answered.
    await expect(second.getByTestId('sync-peers')).toContainText(`Device ${code}`);
    expect(await overflowsHorizontally(second)).toBe(false);
    await second.goto('/en/people/');
    await expect(second.getByRole('list', { name: 'People' }).getByRole('link', { name: 'Mama', exact: true })).toBeVisible();

    // The same file again changes nothing.
    await second.goto('/en/sync/');
    await second.getByTestId('sync-input').setInputFiles(path);
    await expect(second.getByTestId('sync-import-result')).toContainText('Everything in this file was already in the archive', { timeout: 60_000 });

    // A file made by this very device is refused calmly.
    await page.getByTestId('sync-input').setInputFiles(path);
    await expect(page.getByTestId('sync-import-result')).toContainText('This file was made by this device', { timeout: 60_000 });

    expect(foreign, 'requests to non-local origins from the second device').toEqual([]);
  } finally {
    await context.close();
    rmSync(dir, { recursive: true, force: true });
  }
});

/** Renames the only person to `name` through the edit form. */
async function rename(page: Page, from: string, name: string) {
  await page.goto('/en/people/');
  await page.getByRole('list', { name: 'People' }).getByRole('link', { name: from }).click();
  await personMenu(page, from, `Edit ${from}`);
  await page.getByLabel('Name', { exact: true }).fill(name);
  await page.getByRole('button', { name: 'Save changes' }).click();
  await expect(page.getByRole('heading', { level: 1, name })).toBeVisible();
}

test('a person renamed on two devices is kept side by side and settled by choice', async ({ page, browser }, testInfo) => {
  test.setTimeout(150_000);
  const dir = mkdtempSync(join(tmpdir(), 'ma-sync-conflict-e2e-'));
  const use = testInfo.project.use;
  const context = await browser.newContext({
    baseURL: use.baseURL!,
    locale: 'en-US',
    viewport: use.viewport,
    isMobile: use.isMobile,
    hasTouch: use.hasTouch,
    deviceScaleFactor: use.deviceScaleFactor,
    acceptDownloads: true,
  });
  const makeFile = async (device: Page, name: string) => {
    await device.goto('/en/sync/');
    const downloading = device.waitForEvent('download');
    await device.getByRole('button', { name: 'Make the file' }).click();
    const download = await downloading;
    await expect(device.getByTestId('sync-export-result')).toContainText('The file was made', { timeout: 60_000 });
    const path = join(dir, name);
    await download.saveAs(path);
    return path;
  };
  try {
    await startFresh(page);
    await addPerson(page, 'Mama');
    const first = await makeFile(page, 'first.zip');

    const second = await context.newPage();
    await startFresh(second);
    await second.goto('/en/sync/');
    await second.getByTestId('sync-input').setInputFiles(first);
    await expect(second.getByTestId('sync-import-result')).toContainText('The changes were added', { timeout: 60_000 });
    await expect(second.locator('#sync-conflicts')).toContainText('No conflicts');

    // The same person is renamed on both, then device A sends everything again.
    await rename(second, 'Mama', 'Mama B');
    await rename(page, 'Mama', 'Mama A');
    const again = await makeFile(page, 'again.zip');
    await second.goto('/en/sync/');
    await second.getByTestId('sync-input').setInputFiles(again);
    await expect(second.getByTestId('sync-import-result')).toContainText('1 item was changed on both devices', { timeout: 60_000 });
    await second.getByRole('link', { name: 'Review them' }).click();
    const card = second.locator('#sync-conflicts');
    await expect(card).toContainText('Mama A');
    await expect(card).toContainText('Mama B');
    expect(await overflowsHorizontally(second)).toBe(false);

    // Nothing is chosen for the person: Apply waits.
    await expect(card.getByRole('button', { name: 'Apply' })).toHaveAttribute('aria-disabled', 'true');
    await card.getByRole('radio', { name: /Take the other device/ }).check();
    await card.getByRole('button', { name: 'Apply' }).click();
    await expect(card).toContainText('No conflicts');
    await expect(card.getByRole('status')).toHaveText('Took the other device\u2019s version.');

    await second.goto('/en/people/');
    await expect(second.getByRole('list', { name: 'People' }).getByRole('link', { name: 'Mama A', exact: true })).toBeVisible();
  } finally {
    await context.close();
    rmSync(dir, { recursive: true, force: true });
  }
});
